ee:message.ee:set-payload:
%dw 2.0
output application/json
---
{
	doCompletarOrdenInventario: {
		PeticionCompletarOrdenInventario: {
			EncabezadoMensaje: {
				IdDisponibilidad: payload.completeInventoryOrder.messageHeader.availabilityId,
				NumeroOrdenAprovisionador: payload.completeInventoryOrder.messageHeader.provisioningOrderNumber,
				NumeroRevision: payload.completeInventoryOrder.messageHeader.revisionNumber,
				FechaPeticionOrden: payload.completeInventoryOrder.messageHeader.orderRequestDate,
				TecnologiaETB: payload.completeInventoryOrder.messageHeader.etbTechnology
			},
			DetalleMensaje: {
				CuentasServicio: {
					CuentaServicio: payload.completeInventoryOrder.detail.serviceAccounts.serviceAccount map (sa) -> {
						IdCuentaServicio: sa.serviceAccountId,
						ServiciosCompletar: sa.servicesToComplete map (svc) -> {
							IdServicio: svc.serviceId,
							Accion: svc.action,
							Equipos: svc.equipments map (eq) -> {
								IdServicio: eq.serviceId,
								SerialEquipo: eq.equipmentSerial,
								MacEquipo: eq.equipmentMac,
								EstadoEquipo: eq.equipmentStatus,
								Accion: eq.action,
								Puertos: eq.ports map (p) -> {
									NombrePuerto: p.portName,
									ServiciosPuerto: {
										IdServicioPuerto: p.portServices.portServiceId
									}
								}
							}
						}
					},
					Origen: payload.completeInventoryOrder.detail.serviceAccounts.source
				}
			}
		}
	}
}

%dw 2.0
output application/json
var src = payload.objConfiguracionInventario
var code = payload.cod_res as Number
---
{
	status: code,
	code: if ( code == 200 ) "OK" else "Error",
	message: {
		message: if ( code == 200 ) "Successful Transaction." else "Error Transaction."
	},
	completeInventoryOrderResponse: {
		messageHeader: {
			availabilityId: payload.doCompletarOrdenInventarioResponse.RespuestaPeticionCompletarOrdenInventario.EncabezadoMensaje.IdDisponibilidad,
			provisioningOrderNumber: payload.doCompletarOrdenInventarioResponse.RespuestaPeticionCompletarOrdenInventario.EncabezadoMensaje.NumeroOrdenAprovisionador,
			revisionNumber: payload.doCompletarOrdenInventarioResponse.RespuestaPeticionCompletarOrdenInventario.EncabezadoMensaje.NumeroRevision,
			orderRequestDate: payload.doCompletarOrdenInventarioResponse.RespuestaPeticionCompletarOrdenInventario.EncabezadoMensaje.FechaPeticionOrden,
			etbTechnology: payload.doCompletarOrdenInventarioResponse.RespuestaPeticionCompletarOrdenInventario.EncabezadoMensaje.TecnologiaETB
		}
	}
}
